# Modified by Wisp: drop the GPU power cap now, even while capped requests
# still run (they finish uncapped), so an app that starts using the GPU in the
# middle of a capped request is not held under it. The cap is Mac-wide.
@app.post("/v1/wisp/gpu-power/lift")
async def wisp_lift_gpu_power(_: bool = Depends(verify_api_key)):
    limiter = _server_state.gpu_power_limiter
    if limiter is not None:
        await limiter.close()
    return {"status": "ok"}


